# Generated by robot-overlord's scripts/update-tap.sh on each stable release.
class Rlord < Formula
  desc "Run and organize many AI coding-agent sessions in tmux"
  homepage "https://github.com/robot-lord/robot-overlord"
  version "1.0.0"
  license any_of: ["MIT", "Apache-2.0"]

  on_macos do
    on_arm do
      url "https://github.com/robot-lord/robot-overlord/releases/download/v1.0.0/rlord-v1.0.0-aarch64-apple-darwin.tar.gz"
      sha256 "f62dbca7cc548ebb9361710895db56cb50a407e4a5c32cb4b6bacbc65be67cb8"
    end
  end


  depends_on "tmux"

  def install
    bin.install "rlord"
  end

  def caveats
    <<~EOS
      Once: rlord claude install-hooks   (lets rlord see Claude Code's state)
      Then: rlord
    EOS
  end

  test do
    assert_match "rlord #{version}", shell_output("#{bin}/rlord --version")
  end
end
